import { Component, EventEmitter, Output, OnInit } from '@angular/core';
import { FormBuilder, FormGroup } from '@angular/forms';
import { StatutArchive, TypeMarche, FiltreRecherche } from '../../models/marche.model';
import { REGIONS, COMMUNES } from '../../data/regions.data';

@Component({
  selector: 'app-recherche-marche',
  templateUrl: './recherche-marche.component.html',
  styleUrls: ['./recherche-marche.component.scss']
})
export class RechercheMarcheComponent implements OnInit {
  @Output() search = new EventEmitter<FiltreRecherche>();

  filtersVisible: boolean = true;
  totalResults: number | null = null;
  tempsRecherche: number = 0;

  regions = REGIONS;
  departements: any[] = [];
  communes: any[] = [];

  searchForm: FormGroup;

  statutOptions = [
    { value: 'ACTIF', label: '✅ Actif' },
    { value: 'EN_COURS', label: '⏳ En cours' },
    { value: 'EN_ATTENTE', label: '⏳ En attente' },
    { value: 'ARCHIVE', label: '📁 Archivé' },
    { value: 'ANNULE', label: '❌ Annulé' }
  ];

  typeOptions = [
    { value: 'PRESTATION_SERVICE', label: 'Prestation de service' },
    { value: 'PRESTATION_INTELLECTUELLE', label: 'Prestation intellectuelle' },
    { value: 'FOURNITURE', label: 'Fourniture' },
    { value: 'TRAVAUX', label: 'Travaux' },
    { value: 'AUTRE', label: 'Autre' }
  ];

  constructor(private fb: FormBuilder) {
    this.searchForm = this.fb.group({
      motCle: [''],
      direction: [''],
      statut: [''],
      type: [''],
      dateDebut: [''],
      dateFin: [''],
      montantMin: [''],
      montantMax: [''],
      region: [''],
      departement: [''],
      commune: [''],
      titulaire: [''],
      reference: ['']
    });
  }

  ngOnInit(): void {
    // ✅ Surveiller les changements de région
    this.searchForm.get('region')?.valueChanges.subscribe((regionCode: string) => {
      console.log('🔵 Recherche - Région sélectionnée:', regionCode);
      this.onRegionChange(regionCode);
    });

    // ✅ Surveiller les changements de département
    this.searchForm.get('departement')?.valueChanges.subscribe((deptCode: string) => {
      console.log('🟢 Recherche - Département sélectionné:', deptCode);
      this.onDepartementChange(deptCode);
    });
  }

  // ✅ Méthode appelée quand la région change
  onRegionChange(regionCode: string): void {
    if (regionCode) {
      const region = this.regions.find(r => r.code === regionCode);
      this.departements = region?.departements || [];
      this.searchForm.get('departement')?.setValue('');
      this.searchForm.get('commune')?.setValue('');
      this.communes = [];
    } else {
      this.departements = [];
      this.communes = [];
    }
    this.onSearch();
  }

  // ✅ Méthode appelée quand le département change
  onDepartementChange(deptCode: string): void {
    if (deptCode) {
      this.communes = COMMUNES[deptCode] || [];
      this.searchForm.get('commune')?.setValue('');
    } else {
      this.communes = [];
    }
    this.onSearch();
  }

  // ✅ Méthode appelée depuis le HTML (change)
  onRegionSelect(event: any): void {
    const regionCode = event.target.value;
    console.log('🔴 Recherche - onRegionSelect:', regionCode);
    this.onRegionChange(regionCode);
  }

  // ✅ Méthode appelée depuis le HTML (change)
  onDepartementSelect(event: any): void {
    const deptCode = event.target.value;
    console.log('🔴 Recherche - onDepartementSelect:', deptCode);
    this.onDepartementChange(deptCode);
  }

  onSearch(): void {
    const debut = Date.now();
    const formValues = this.searchForm.value;

    const filtres: FiltreRecherche = {
      motCle: formValues.motCle || undefined,
      direction: formValues.direction || undefined,
      statut: formValues.statut || undefined,
      type: formValues.type || undefined,
      dateDebut: formValues.dateDebut || undefined,
      dateFin: formValues.dateFin || undefined,
      montantMin: formValues.montantMin || undefined,
      montantMax: formValues.montantMax || undefined,
      region: formValues.region || undefined,
      departement: formValues.departement || undefined,
      commune: formValues.commune || undefined,
      titulaire: formValues.titulaire || undefined,
      reference: formValues.reference || undefined
    };

    this.search.emit(filtres);
    this.tempsRecherche = Date.now() - debut;
  }

  resetFilters(): void {
    this.searchForm.reset({
      statut: '',
      type: '',
      region: '',
      departement: '',
      commune: ''
    });
    this.departements = [];
    this.communes = [];
    this.onSearch();
  }

  clearSearch(): void {
    this.searchForm.get('motCle')?.setValue('');
    this.onSearch();
  }
}
<div class="recherche-container">
  <div class="recherche-header">
    <h3>🔍 Recherche avancée</h3>
    <button class="btn-toggle" (click)="filtersVisible = !filtersVisible">
      {{ filtersVisible ? 'Masquer les filtres ▲' : 'Afficher les filtres ▼' }}
    </button>
  </div>

  <div class="search-bar">
    <div class="search-input-wrapper">
      <span class="search-icon">🔍</span>
      <input 
        type="text" 
        formControlName="motCle"
        (input)="onSearch()"
        placeholder="Rechercher par référence, objet, titulaire, direction, région..."
        class="search-input"
      >
      <button class="btn-clear" *ngIf="searchForm.get('motCle')?.value" (click)="clearSearch()">✕</button>
    </div>
    <button class="btn-search" (click)="onSearch()">Rechercher</button>
  </div>

  <div class="filters-panel" *ngIf="filtersVisible">
    <div class="filters-grid">

      <div class="filter-group">
        <label>📌 Référence</label>
        <input type="text" formControlName="reference" (input)="onSearch()" placeholder="M-2024-001" class="filter-input">
      </div>

      <div class="filter-group">
        <label>🏢 Direction</label>
        <input type="text" formControlName="direction" (input)="onSearch()" placeholder="DSI, DAG, DAO..." class="filter-input">
      </div>

      <div class="filter-group">
        <label>🏢 Titulaire</label>
        <input type="text" formControlName="titulaire" (input)="onSearch()" placeholder="Nom de l'entreprise" class="filter-input">
      </div>

      <div class="filter-group">
        <label>📊 Statut</label>
        <select formControlName="statut" (change)="onSearch()" class="filter-select">
          <option value="">Tous les statuts</option>
          <option *ngFor="let opt of statutOptions" [value]="opt.value">{{ opt.label }}</option>
        </select>
      </div>

      <div class="filter-group">
        <label>📂 Type</label>
        <select formControlName="type" (change)="onSearch()" class="filter-select">
          <option value="">Tous les types</option>
          <option *ngFor="let opt of typeOptions" [value]="opt.value">{{ opt.label }}</option>
        </select>
      </div>

      <!-- ===== RÉGION (avec (change) pour forcer la mise à jour) ===== -->
      <div class="filter-group">
        <label>🗺️ Région</label>
        <select formControlName="region" (change)="onRegionSelect($event); onSearch()" class="filter-select">
          <option value="">Toutes les régions</option>
          <option *ngFor="let r of regions" [value]="r.code">{{ r.nom }}</option>
        </select>
      </div>

      <!-- ===== DÉPARTEMENT ===== -->
      <div class="filter-group">
        <label>📍 Département</label>
        <select formControlName="departement" (change)="onDepartementSelect($event); onSearch()" class="filter-select" [disabled]="!departements.length">
          <option value="">Tous les départements</option>
          <option *ngFor="let d of departements" [value]="d.code">{{ d.nom }}</option>
        </select>
      </div>

      <!-- ===== COMMUNE ===== -->
      <div class="filter-group">
        <label>🏘️ Commune</label>
        <select formControlName="commune" (change)="onSearch()" class="filter-select" [disabled]="!communes.length">
          <option value="">Toutes les communes</option>
          <option *ngFor="let c of communes" [value]="c.code">{{ c.nom }}</option>
        </select>
      </div>

      <div class="filter-group">
        <label>📅 Date début</label>
        <input type="date" formControlName="dateDebut" (change)="onSearch()" class="filter-input">
      </div>

      <div class="filter-group">
        <label>📅 Date fin</label>
        <input type="date" formControlName="dateFin" (change)="onSearch()" class="filter-input">
      </div>

      <div class="filter-group">
        <label>💰 Montant min (FCFA)</label>
        <input type="number" formControlName="montantMin" (input)="onSearch()" placeholder="0" class="filter-input">
      </div>

      <div class="filter-group">
        <label>💰 Montant max (FCFA)</label>
        <input type="number" formControlName="montantMax" (input)="onSearch()" placeholder="100000000" class="filter-input">
      </div>
    </div>

    <div class="filters-actions">
      <button class="btn-reset" (click)="resetFilters()">🔄 Réinitialiser</button>
      <span class="results-info" *ngIf="totalResults !== null">
        {{ totalResults }} résultat(s) trouvé(s) - {{ tempsRecherche }} ms
      </span>
    </div>
  </div>
</div>
